SELECT cdscode
FROM frpm
WHERE (COALESCE("Enrollment (K-12)",0) + COALESCE("Enrollment (Ages 5-17)",0)) > 500;

SELECT CAST(SUM(CASE WHEN status = 'C' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS pct_running_ok
FROM loan
WHERE amount < 100000;

SELECT EXISTS (
  SELECT 1
  FROM cards c
  JOIN set_translations st ON c.setcode = st.setcode
  WHERE c.name = 'Ancestor''s Chosen' AND st.language = 'Korean'
) AS has_korean_version;

SELECT CAST(SUM(CASE WHEN admission = '-' THEN 1 ELSE 0 END) AS REAL) / NULLIF(SUM(CASE WHEN admission = '+' THEN 1 ELSE 0 END), 0) AS outpatient_to_inpatient_ratio
FROM patient
WHERE diagnosis = 'SLE';
